+
+		var check = func(t *testing.T, buf []byte) {
+			set, err := jwk.Parse(buf)
+			if !assert.NoError(t, err, `jwk.Parse should succeed`) {
+				return
+			}
+
+			if !assert.Equal(t, 1, set.Len(), `set.Len() should be 1`) {
