+			if !assert.Equal(t, `foo`, v, `set.Field("renewal_kid") should return "foo"`) {
+				return
+			}
+
+			key, ok := set.Get(0)
+			if !assert.True(t, ok, `set.Get(0) should return ok = true`) {
+				return
+			}
+
+			v, ok = key.Get(`renewal_kid`)
+			if !assert.True(t, ok, `key.Get("renewal_kid") should return ok = true`) {
